#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int n = (int)readInt(), r = (int)readInt();
    // Array trie: child[node * 26 + letter], 0 = absent (node 0 is the root).
    vector<int> child(26, 0);
    vector<char> terminal(1, 0);
    for (int i = 0; i < n; i++) {
        string w = readToken();
        int node = 0;
        for (char ch : w) {
            int &next = child[node * 26 + (ch - 'a')];
            if (!next) {
                next = (int)terminal.size();
                terminal.push_back(0);
                child.resize(child.size() + 26, 0);
            }
            node = child[node * 26 + (ch - 'a')];
        }
        terminal[node] = 1;
    }
    string out;
    for (int t = 0; t < r; t++) {
        string w = readToken();
        int len = (int)w.size();
        // dp[i]: the first i characters split into ingredients.
        vector<char> dp(len + 1, 0);
        dp[0] = 1;
        for (int i = 0; i < len; i++) {
            if (!dp[i]) continue;
            int node = 0;
            for (int j = i; j < len; j++) {
                node = child[node * 26 + (w[j] - 'a')];
                if (!node) break;
                if (terminal[node]) dp[j + 1] = 1;
            }
        }
        if (t) out.push_back(' ');
        out += dp[len] ? "YES" : "NO";
    }
    puts(out.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), r = nextInt();
        String[] words = new String[n];
        int total = 1;
        for (int i = 0; i < n; i++) {
            words[i] = next();
            total += words[i].length();
        }
        // Array trie: child[node * 26 + letter], 0 = absent (node 0 is the root).
        int[] child = new int[total * 26];
        boolean[] terminal = new boolean[total];
        int nodes = 1;
        for (String w : words) {
            int node = 0;
            for (int i = 0; i < w.length(); i++) {
                int idx = node * 26 + (w.charAt(i) - 'a');
                if (child[idx] == 0) child[idx] = nodes++;
                node = child[idx];
            }
            terminal[node] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < r; t++) {
            String w = next();
            int len = w.length();
            boolean[] dp = new boolean[len + 1];
            dp[0] = true;
            for (int i = 0; i < len; i++) {
                if (!dp[i]) continue;
                int node = 0;
                for (int j = i; j < len; j++) {
                    node = child[node * 26 + (w.charAt(j) - 'a')];
                    if (node == 0) break;
                    if (terminal[node]) dp[j + 1] = true;
                }
            }
            if (t > 0) sb.append(' ');
            sb.append(dp[len] ? "YES" : "NO");
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, r := nextInt(), nextInt()
	// Array trie: child[node*26+letter], 0 = absent (node 0 is the root).
	child := make([]int32, 26)
	terminal := []bool{false}
	for i := 0; i < n; i++ {
		node := int32(0)
		for _, ch := range token() {
			idx := int(node)*26 + int(ch-'a')
			if child[idx] == 0 {
				child[idx] = int32(len(terminal))
				terminal = append(terminal, false)
				child = append(child, make([]int32, 26)...)
			}
			node = child[idx]
		}
		terminal[node] = true
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for t := 0; t < r; t++ {
		w := token()
		dp := make([]bool, len(w)+1)
		dp[0] = true
		for i := range w {
			if !dp[i] {
				continue
			}
			node := int32(0)
			for j := i; j < len(w); j++ {
				node = child[int(node)*26+int(w[j]-'a')]
				if node == 0 {
					break
				}
				if terminal[node] {
					dp[j+1] = true
				}
			}
		}
		if t > 0 {
			out.WriteByte(' ')
		}
		if dp[len(w)] {
			out.WriteString("YES")
		} else {
			out.WriteString("NO")
		}
	}
	out.WriteByte('\n')
}
